content:
/* Portada, directorio de marcas y empleos del sitio institucional. Mobile first. */

/* Botones de portada */
.home-button { display: inline-flex; align-items: center; justify-content: center; min-height: 50px; padding: 0 24px; border-radius: 999px; font-size: 15px; font-weight: 750; text-decoration: none; transition: background var(--dur-base) var(--ease-out), color var(--dur-base) var(--ease-out), border-color var(--dur-base) var(--ease-out); }
.home-button--lime { background: var(--lime); color: var(--ink-deep); }
.home-button--lime:hover { background: #c4dc1c; color: var(--ink-deep); }
.home-button--ghost { border: 1.5px solid rgb(255 255 255 / .75); color: white; }
.home-button--ghost:hover { background: white; color: var(--ink-deep); }
.home-button--ink { border: 1.5px solid var(--ink); color: var(--ink); }
.home-button--ink:hover { background: var(--ink); color: white; }
.home-text-link { align-self: flex-start; padding-block: 8px; color: var(--ink); font-weight: 750; text-decoration: underline; text-decoration-color: var(--lime); text-decoration-thickness: 2px; text-underline-offset: 5px; }
.home-text-link:hover { color: var(--ink-deep); }

/* Hero a sangre: el header transparente queda encima hasta que se hace scroll */
.home-hero { position: relative; isolation: isolate; height: clamp(600px, 100svh, 800px); overflow: hidden; background: var(--ink-deep); color: white; }
.home-slide { position: absolute; inset: 0; opacity: 0; visibility: hidden; transition: opacity 900ms ease, visibility 0s linear 900ms; }
.home-slide.is-on { opacity: 1; visibility: visible; transition: opacity 900ms ease; }
.home-slide > picture { display: block; width: 100%; height: 100%; }
.home-slide > img, .home-slide > picture > img { width: 100%; height: 100%; object-fit: cover; transform: scale(1.05); transition: transform 8s ease-out; }
.home-slide.is-on > img, .home-slide.is-on > picture > img { transform: none; }
.home-slide::after { content: ""; position: absolute; inset: 0; background: linear-gradient(0deg, rgb(13 38 47 / .88) 0%, rgb(13 38 47 / .45) 55%, rgb(13 38 47 / .3) 100%); }
.home-slide-copy { position: absolute; z-index: 1; inset: auto 0 108px; }
.home-slide-copy h1, .home-slide-copy h2 { max-width: 660px; font-size: clamp(36px, 5.2vw, 64px); font-weight: 800; line-height: 1.04; letter-spacing: -.035em; text-wrap: balance; }
.home-slide-copy p { max-width: 540px; margin-top: 16px; color: rgb(255 255 255 / .9); font-size: clamp(16px, 1.4vw, 19px); line-height: 1.55; }
.home-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
.home-hero-controls { position: absolute; z-index: 2; inset: auto 0 32px; }
.home-hero-controls .container { display: flex; align-items: center; gap: 12px; }
.home-dots { display: flex; gap: 6px; }
.home-dots button { position: relative; width: 36px; height: 44px; padding: 0; border: 0; background: none; cursor: pointer; }
.home-dots button::before { content: ""; position: absolute; inset: 20px 0 auto; height: 3px; border-radius: 2px; background: rgb(255 255 255 / .4); transition: background var(--dur-base) ease; }
.home-dots button.is-on::before { background: var(--lime); }
.home-round { display: grid; place-items: center; width: 44px; height: 44px; padding: 0; border: 1.5px solid rgb(255 255 255 / .6); border-radius: 999px; background: transparent; color: white; cursor: pointer; transition: background var(--dur-base) ease, color var(--dur-base) ease; }
.home-round:hover { background: white; color: var(--ink-deep); }
.home-hero :focus-visible { outline: 3px solid var(--lime); outline-offset: 3px; }
.home-arrows { display: flex; gap: 8px; margin-left: auto; }

/* Cifras */
.home-stats { position: relative; isolation: isolate; overflow: hidden; padding-block: 28px 16px; background: white; }
.home-stats::before { content: ""; position: absolute; z-index: -1; width: 120%; height: 460px; left: -10%; top: 76px; border: 54px solid #edf4f5; border-radius: 50%; box-sizing: border-box; pointer-events: none; }
.home-stats-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px 20px; }
.home-stat { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; min-width: 0; }
.home-stat-icon { display: grid; place-items: center; width: 44px; height: 44px; margin-bottom: 2px; border-radius: 50%; background: var(--lime); color: var(--ink-deep); }
.home-stat-icon svg { width: 24px; height: 24px; }
.home-stat strong { display: block; color: var(--ink); font-size: clamp(23px, 2.4vw, 32px); font-weight: 800; letter-spacing: -.03em; line-height: 1.2; }
.home-stat-description { display: block; max-width: 260px; color: var(--text); font-size: 14px; line-height: 1.55; }

/* Secciones */
.home-section { padding-block: clamp(72px, 9vw, 120px); }
.home-stats + .home-section { padding-top: clamp(32px, 4vw, 48px); }
.home-section--paper { background: var(--paper); }
.home-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 16px 48px; margin-bottom: clamp(28px, 4vw, 48px); }
.home-head h2, .home-about h2, .home-jobs h2 { max-width: 640px; color: var(--ink-deep); font-size: clamp(32px, 4vw, 48px); font-weight: 800; line-height: 1.05; letter-spacing: -.035em; }
.home-head p { max-width: 440px; color: var(--text); font-size: clamp(15px, 1.3vw, 18px); line-height: 1.6; }

/* Qué distribuimos */
.home-lines { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.home-line { position: relative; display: flex; flex-direction: column; padding: 18px; overflow: hidden; border-radius: 20px; background: var(--paper); color: var(--ink-deep); transition: background var(--dur-base) var(--ease-out); }
.home-line--wide { grid-column: span 2; padding: 26px; }
.home-line:hover { background: #e7ebdb; color: var(--ink-deep); }
.home-line h3 { margin-bottom: 8px; font-size: 17px; font-weight: 800; line-height: 1.15; letter-spacing: -.015em; }
.home-line--wide h3 { font-size: 21px; }
.home-line p { color: var(--text); font-size: 13px; line-height: 1.5; }
.home-line-count { margin-top: auto; padding-top: 16px; color: var(--lime-text); font-size: 13px; font-weight: 750; }
.home-line-pic, .home-line-trio { display: flex; align-self: center; align-items: flex-end; height: 120px; margin-top: 14px; transition: transform 400ms var(--ease-out); }
.home-line-pic img, .home-line-trio img { width: auto; max-width: 100%; height: 100%; object-fit: contain; object-position: bottom; }
.home-line-trio { height: 170px; }
.home-line-trio img + img { margin-left: -24px; }
.home-line-trio img:nth-child(2) { height: 88%; }
.home-line-trio img:nth-child(3) { height: 76%; }
.home-line:hover .home-line-pic, .home-line:hover .home-line-trio { transform: translateY(-8px); }
.home-line--dark { background: var(--ink); color: white; }
.home-line--dark:hover { background: var(--ink-deep); color: white; }
.home-line--dark p { max-width: 100%; color: var(--on-ink-muted); }
.home-line--dark .home-line-count { color: var(--lime); }

/* Marcas destacadas */
.home-tabs { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(140px, 1fr); gap: 10px; margin-bottom: 20px; overflow-x: auto; padding-bottom: 6px; scrollbar-width: thin; }
.home-tabs button { position: relative; display: grid; place-items: center; height: 96px; padding: 16px 22px; border: 0; border-radius: 18px; background: white; cursor: pointer; transition: box-shadow var(--dur-base) ease; }
.home-tabs img { max-width: 100%; max-height: 52px; object-fit: contain; filter: grayscale(1); opacity: .55; transition: filter var(--dur-base) ease, opacity var(--dur-base) ease; }
.home-tabs button:hover img, .home-tabs button.is-on img { filter: none; opacity: 1; }
.home-tabs button::after { content: ""; position: absolute; inset: auto 22px 0; height: 4px; border-radius: 4px 4px 0 0; background: var(--ink); transform: scaleX(0); transition: transform 300ms var(--ease-out); }
.home-tabs button.is-on::after { transform: none; }
.home-tabs button.is-on { box-shadow: 0 14px 34px rgb(22 61 74 / .1); }
.home-tabs button:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; }
.home-panel { display: grid; overflow: hidden; border-radius: 24px; background: white; animation: home-fade 450ms var(--ease-out) both; }
.home-panel-photo { position: relative; height: 240px; }
.home-panel-photo img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.home-panel-body { display: flex; flex-direction: column; gap: 16px; padding: 28px 22px; }
.home-panel-logo { width: auto; max-width: 240px; height: 56px; object-fit: contain; object-position: left; }
.home-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.home-chips span { padding: 6px 12px; border-radius: 999px; background: var(--lime-soft); color: #4a5a00; font-size: 13px; font-weight: 750; }
.home-panel-text { max-width: 560px; color: #33474e; font-size: clamp(15px, 1.3vw, 18px); line-height: 1.6; }
.home-shelf { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 16px; margin: auto 0 0; padding: 8px 0 0; list-style: none; }
.home-shelf li { flex: 1 1 0; min-width: 104px; max-width: 165px; text-align: center; }
.home-shelf-img { display: flex; align-items: flex-end; justify-content: center; height: 170px; padding-bottom: 10px; border-bottom: 2px solid var(--line); }
.home-shelf-img img { max-width: 100%; max-height: 100%; object-fit: contain; transition: transform 350ms var(--ease-out); }
.home-shelf li:hover img { transform: translateY(-6px); }
.home-shelf li > span:last-child { display: block; margin-top: 10px; color: #33474e; font-size: 13px; font-weight: 650; line-height: 1.35; }
@keyframes home-fade { from { opacity: 0; transform: translateY(8px); } }

/* Pseudo banner «Explorá nuestras marcas» */
.home-explore { position: relative; isolation: isolate; display: block; min-height: 460px; overflow: hidden; border-radius: 28px; background: var(--ink-deep); color: white; }
.home-explore:hover { color: white; }
.home-explore::before { content: ""; position: absolute; inset: 0; z-index: -1; background: rgb(22 61 74 / .45); }
.home-explore-bg { position: absolute; z-index: -2; inset: -24px; width: calc(100% + 48px); height: calc(100% + 48px); object-fit: cover; filter: blur(7px) brightness(.5) saturate(.85); }
.home-explore-copy { position: relative; z-index: 2; display: grid; justify-items: start; max-width: 470px; padding: 40px 24px 0; }
.home-explore-title { font-size: clamp(36px, 4.4vw, 54px); font-weight: 800; line-height: 1.02; letter-spacing: -.035em; }
.home-explore-text { margin: 16px 0 28px; color: rgb(255 255 255 / .88); font-size: clamp(16px, 1.4vw, 18px); line-height: 1.55; }
.home-explore:hover .home-button--ghost { background: white; color: var(--ink-deep); }
.home-explore:focus-visible { outline: 3px solid var(--lime); outline-offset: 4px; }
.home-collage { position: relative; z-index: 1; display: block; height: 240px; margin: 24px 16px 0; }
.home-collage img { position: absolute; bottom: 0; width: auto; object-fit: contain; filter: drop-shadow(0 18px 22px rgb(0 0 0 / .38)); transition: transform 500ms var(--ease-out); }
.home-explore:hover .home-collage img { transform: translateY(-10px); }
.home-explore:hover .home-collage img:nth-child(even) { transform: translateY(-5px); }

/* Nosotros */
.home-about { display: grid; gap: 40px; align-items: center; }
.home-about-text { max-width: 560px; margin-top: 20px; color: #33474e; font-size: clamp(16px, 1.4vw, 18px); line-height: 1.65; }
.home-facts { margin: 28px 0 32px; }
.home-facts div { display: grid; grid-template-columns: 120px 1fr; align-items: baseline; gap: 18px; padding-block: 16px; border-top: 1px solid var(--line); }
.home-facts div:last-child { border-bottom: 1px solid var(--line); }
.home-facts dt { white-space: nowrap; color: var(--ink); font-size: clamp(20px, 2vw, 26px); font-weight: 800; letter-spacing: -.02em; }
.home-facts dd { margin: 0; color: var(--text); font-size: 15px; line-height: 1.5; }
.home-mosaic { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: 220px 160px; gap: 12px; }
.home-mosaic img { width: 100%; height: 100%; object-fit: cover; border-radius: 18px; }
.home-mosaic .home-mosaic-big { grid-column: span 2; }

/* Trabajá con nosotros (portada) */
.home-jobs { background: var(--ink); color: white; }
.home-jobs-grid { display: grid; gap: 40px; align-items: center; padding-block: clamp(72px, 8vw, 104px); }
.home-jobs h2 { color: white; }
.home-jobs p { max-width: 520px; margin-top: 16px; color: var(--on-ink-muted); font-size: clamp(16px, 1.4vw, 18px); line-height: 1.6; }
.home-perks { display: flex; flex-wrap: wrap; gap: 10px; margin: 24px 0 32px; padding: 0; list-style: none; }
.home-perks li { padding: 8px 14px; border: 1px solid rgb(255 255 255 / .3); border-radius: 999px; font-size: 14px; font-weight: 650; }
.home-jobs-photo { height: 280px; overflow: hidden; border-radius: 22px; }
.home-jobs-photo img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 40%; }

/* /marcas */
.brands-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 20px; margin-bottom: 20px; }
.brands-search { display: flex; flex: 1 1 320px; align-items: center; gap: 10px; max-width: 520px; height: 54px; padding: 0 18px; border: 1px solid var(--line); border-radius: 999px; color: var(--text); }
.brands-search:focus-within { border-color: var(--ink); box-shadow: 0 0 0 3px var(--lime-soft); }
.brands-search input { flex: 1; min-width: 0; height: 100%; border: 0; outline: 0; background: transparent; color: var(--ink-deep); font-size: 16px; }
.brands-species { display: flex; align-items: center; gap: 10px; color: #33474e; font-size: 14px; font-weight: 750; }
.brands-species select { min-height: 44px; padding: 0 12px; border: 1px solid var(--line); border-radius: 12px; background: white; color: var(--ink-deep); font-weight: 650; }
.site-brand-filters small { margin-left: 4px; color: var(--text); font-size: 12px; font-weight: 750; }
.site-brand-filters button[aria-pressed="true"] small { color: #d7e57a; }
.brands-result { margin: 4px 0 0; color: var(--text); font-size: 14px; font-weight: 650; }
.brands-detail { position: relative; display: grid; margin-top: 28px; overflow: hidden; border-radius: 24px; background: var(--paper); scroll-margin-top: 96px; animation: home-fade 400ms var(--ease-out) both; }
.brands-detail-logo { display: grid; place-items: center; min-height: 170px; padding: 32px; background: white; }
.brands-detail-logo img { max-width: 220px; max-height: 110px; object-fit: contain; }
.brands-detail-body { display: flex; flex-direction: column; gap: 14px; padding: 28px 20px; }
.brands-detail h2 { color: var(--ink-deep); font-size: clamp(28px, 3vw, 38px); font-weight: 800; letter-spacing: -.03em; line-height: 1.05; }
.brands-detail-body > p { max-width: 640px; color: #33474e; font-size: 16px; line-height: 1.6; }
.brands-detail .home-chips span { background: white; color: #33474e; }
.brands-detail .home-chips span:first-child { background: var(--lime-soft); color: #4a5a00; }
.brands-detail .home-shelf-img { border-color: #cfd8da; }
.brands-detail .home-shelf-img img { mix-blend-mode: multiply; }
.brands-close { position: absolute; top: 16px; right: 16px; min-height: 44px; padding: 0 18px; border: 1px solid #c3ccd0; border-radius: 999px; background: white; color: var(--ink); font-weight: 750; cursor: pointer; }
.brands-close:hover { border-color: var(--ink); }
.brands-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 28px; }
.brands-card { display: flex; flex-direction: column; overflow: hidden; padding: 0; border: 1.5px solid var(--line); border-radius: 20px; background: white; color: inherit; text-align: left; cursor: pointer; transition: border-color var(--dur-base) ease, box-shadow var(--dur-base) ease; }
.brands-card:hover { border-color: #b9c6ca; box-shadow: 0 14px 34px rgb(22 61 74 / .09); }
.brands-card[aria-pressed="true"] { border-color: var(--ink); box-shadow: 0 0 0 1.5px var(--ink); }
.brands-card-logo { display: grid; place-items: center; height: 110px; padding: 16px 20px; border-bottom: 1px solid #eef1f2; }
.brands-card-logo img { max-width: 100%; max-height: 64px; object-fit: contain; }
.brands-wordmark { color: var(--ink); font-size: clamp(18px, 2vw, 24px); font-weight: 800; letter-spacing: -.02em; line-height: 1.1; text-align: center; }
.brands-card-name { padding: 14px 16px 0; color: var(--ink-deep); font-size: 16px; font-weight: 800; }
.brands-card-meta { padding: 2px 16px 16px; color: var(--text); font-size: 13px; line-height: 1.4; }
.brands-empty { grid-column: 1 / -1; }

/* /trabajo */
.jobs-intro { position: relative; isolation: isolate; overflow: hidden; padding: 140px 0 56px; background: var(--ink-deep); color: white; }
.jobs-intro::before { content: ""; position: absolute; inset: 0; z-index: -1; background: rgb(22 61 74 / .5); }
.jobs-intro-bg { position: absolute; z-index: -2; inset: -24px; width: calc(100% + 48px); height: calc(100% + 48px); object-fit: cover; object-position: 50% 60%; filter: blur(5px) brightness(.45) saturate(.85); }
.jobs-intro h1 { font-size: clamp(38px, 5vw, 64px); font-weight: 800; letter-spacing: -.035em; line-height: 1.02; }
.jobs-intro p { max-width: 600px; margin-top: 16px; color: rgb(255 255 255 / .88); font-size: clamp(16px, 1.4vw, 19px); line-height: 1.55; }
.jobs-section { padding-top: clamp(32px, 4vw, 48px); }
.jobs-finder { display: grid; gap: 8px; max-width: 860px; margin-bottom: clamp(32px, 4vw, 56px); padding: 8px; border: 1px solid var(--line); border-radius: 20px; background: white; box-shadow: 0 14px 34px rgb(22 61 74 / .08); }
.jobs-field { display: flex; align-items: center; gap: 10px; min-height: 54px; padding: 0 16px; border-radius: 14px; background: #f3f5f5; color: var(--text); }
.jobs-field:focus-within { box-shadow: 0 0 0 3px var(--lime); }
.jobs-field input, .jobs-field select { flex: 1; min-width: 0; height: 54px; border: 0; outline: 0; background: transparent; color: var(--ink-deep); font-size: 16px; }
.jobs-finder .button { min-height: 54px; }
.jobs-body { display: grid; gap: 28px; scroll-margin-top: 96px; }
.jobs-filters { display: grid; align-content: start; gap: 4px; }
.jobs-filters fieldset { margin: 0; padding: 16px 0; border: 0; border-bottom: 1px solid var(--line); }
.jobs-filters legend { margin-bottom: 8px; padding: 0; color: var(--ink-deep); font-size: 14px; font-weight: 800; }
.jobs-filters .button { justify-self: start; margin-top: 12px; }
.jobs-check { display: flex; align-items: center; gap: 12px; min-height: 40px; color: #33474e; font-size: 15px; cursor: pointer; }
.jobs-check input { width: 20px; height: 20px; margin: 0; accent-color: var(--ink); }
.jobs-check small { margin-left: auto; color: var(--text); font-size: 12px; font-weight: 750; }
.jobs-note { margin-bottom: 18px; padding: 12px 16px; border: 1.5px dashed #c3ccd0; border-radius: 14px; color: var(--text); font-size: 14px; line-height: 1.5; }
.jobs-result-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.jobs-result-head h2 { color: var(--ink-deep); font-size: clamp(22px, 2vw, 26px); font-weight: 800; letter-spacing: -.015em; }
.jobs-result-head label { display: flex; align-items: center; gap: 10px; color: #33474e; font-size: 14px; font-weight: 750; }
.jobs-result-head select { min-height: 44px; padding: 0 12px; border: 1px solid var(--line); border-radius: 12px; background: white; color: var(--ink-deep); font-weight: 650; }
.jobs-list { display: grid; gap: 12px; margin: 0; padding: 0; list-style: none; }
.jobs-item { border: 1.5px solid var(--line); border-radius: 20px; background: white; transition: border-color var(--dur-base) ease, box-shadow var(--dur-base) ease; }
.jobs-item:hover { border-color: #b9c6ca; }
.jobs-item.is-open { border-color: var(--ink); box-shadow: 0 14px 34px rgb(22 61 74 / .08); }
.jobs-row { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 20px; padding: 20px; }
.jobs-example { display: inline-block; margin-left: 10px; padding: 3px 8px; border: 1px solid #c3ccd0; border-radius: 4px; font-size: 12px; font-weight: 600; vertical-align: middle; letter-spacing: 0; }
.jobs-more p, .jobs-more li { white-space: pre-line; overflow-wrap: anywhere; }
.jobs-main { flex: 1 1 260px; min-width: 0; }
.jobs-main h3 { margin-bottom: 8px; color: var(--ink-deep); font-size: 19px; font-weight: 800; letter-spacing: -.01em; }
.jobs-meta { display: flex; flex-wrap: wrap; gap: 6px 18px; margin: 0; padding: 0; color: var(--text); font-size: 14px; list-style: none; }
.jobs-meta li { display: inline-flex; align-items: center; gap: 6px; }
.jobs-date { color: var(--text); font-size: 13px; white-space: nowrap; }
.jobs-toggle { min-height: 44px; padding: 0 20px; border: 1.5px solid var(--ink); border-radius: 999px; background: white; color: var(--ink); font-size: 14px; font-weight: 750; white-space: nowrap; cursor: pointer; }
.jobs-toggle:hover, .jobs-item.is-open .jobs-toggle { background: var(--ink); color: white; }
.jobs-more { display: grid; gap: 16px 40px; margin: 0 20px; padding: 22px 0 26px; border-top: 1px solid #eef1f2; }
.jobs-more > p { color: #33474e; font-size: 16px; line-height: 1.6; }
.jobs-more h4 { margin-bottom: 8px; color: var(--ink-deep); font-size: 14px; font-weight: 800; }
.jobs-more ul { margin: 0; padding-left: 18px; color: #33474e; font-size: 15px; line-height: 1.6; }
.jobs-more .button { justify-self: start; }
.jobs-empty h2 { color: var(--ink-deep); font-size: 22px; font-weight: 800; }
.jobs-cv { background: var(--ink); color: white; }
.jobs-cv-inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 24px 48px; padding-block: 56px; }
.jobs-cv h2 { font-size: clamp(26px, 3vw, 36px); font-weight: 800; letter-spacing: -.025em; line-height: 1.08; }
.jobs-cv p { max-width: 560px; margin-top: 10px; color: var(--on-ink-muted); font-size: 17px; line-height: 1.55; }
.jobs-values { display: grid; gap: 20px; margin: 48px 0 0; padding-top: 32px; border-top: 1px solid var(--line); }
.jobs-values dt { color: var(--ink); font-size: 17px; font-weight: 800; }
.jobs-values dd { margin: 6px 0 0; color: var(--text); font-size: 14px; line-height: 1.55; }

@media (min-width: 768px) {
  .home-slide::after { background: linear-gradient(90deg, rgb(13 38 47 / .8) 0%, rgb(13 38 47 / .5) 42%, rgb(13 38 47 / 0) 72%), linear-gradient(180deg, rgb(13 38 47 / .55) 0%, rgb(13 38 47 / 0) 24%); }
  .home-slide-copy { bottom: 132px; }
  .home-hero-controls { bottom: 40px; }
  .home-stats { padding-block: 36px 20px; }
  .home-stats::before { height: 360px; top: 88px; }
  .home-stats-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: clamp(24px, 4vw, 56px); }
  .home-stat:nth-child(2), .home-stat:nth-child(3) { padding-top: 18px; }
  .home-stat-icon { width: 50px; height: 50px; }
  .home-stat-description { font-size: 15px; }
  .home-lines { gap: 14px; }
  .home-line { min-height: 290px; padding: 26px; }
  .home-line h3 { max-width: 62%; font-size: 21px; }
  .home-line--wide h3 { font-size: 30px; }
  .home-line p { max-width: 56%; font-size: 14px; }
  .home-line-pic, .home-line-trio { height: 205px; }
  .home-line-pic { position: absolute; right: 14px; bottom: 0; max-width: 46%; margin: 0; }
  .home-line-trio { align-self: flex-end; }
  .home-line--wide h3, .home-line--wide p, .home-line--wide .home-line-count { max-width: 42%; }
  .home-line--wide .home-line-trio { position: absolute; right: 14px; bottom: 0; height: 210px; margin: 0; }
  .home-tabs { grid-auto-flow: initial; grid-template-columns: repeat(5, minmax(0, 1fr)); overflow: visible; }
  .home-tabs button { height: 108px; }
  .home-panel-photo { height: 300px; }
  .home-panel-body { padding: 44px 48px; }
  .home-explore-copy { padding: 76px 72px; }
  .home-collage { position: absolute; right: 36px; bottom: 0; width: 52%; height: 90%; margin: 0; }
  .home-mosaic { grid-template-rows: 300px 220px; }
  .home-jobs-photo { height: 380px; }
  .brands-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
  .brands-card-logo { height: 150px; padding: 24px 28px; }
  .brands-card-name { padding: 18px 20px 0; font-size: 17px; }
  .brands-card-meta { padding: 4px 20px 20px; }
  .brands-detail { grid-template-columns: 300px 1fr; }
  .brands-detail-logo { min-height: 260px; }
  .brands-detail-body { padding: 40px 48px; }
  .brands-detail h2 { padding-right: 110px; }
  .jobs-intro { padding: 176px 0 72px; }
  .jobs-finder { grid-template-columns: 1.6fr 1fr auto; }
  .jobs-row { flex-wrap: nowrap; padding: 24px 26px; }
  .jobs-more { grid-template-columns: 1fr 1fr; margin: 0 26px; }
  .jobs-more > p, .jobs-more .button { grid-column: 1 / -1; }
  .jobs-values { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1024px) {
  .home-lines { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; }
  .home-panel { grid-template-columns: 5fr 7fr; min-height: 560px; }
  .home-panel-photo { height: auto; }
  .home-about { grid-template-columns: 5fr 6fr; gap: 72px; }
  .home-jobs-grid { grid-template-columns: 6fr 5fr; gap: 72px; }
  .home-jobs-photo { height: 400px; }
  .brands-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; }
  .jobs-body { grid-template-columns: 260px minmax(0, 1fr); gap: 48px; }
  .jobs-values { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (prefers-reduced-motion: reduce) {
  .home-slide, .home-slide.is-on, .home-slide > img, .home-slide > picture > img, .home-panel, .brands-detail, .home-line-pic, .home-line-trio, .home-collage img, .home-shelf-img img { transition: none; animation: none; transform: none; }
}
